function validate([operations, args]) {
  if (operations.length !== args.length) return 'operations and arguments need the same length.';
  if (operations[0] !== 'MovingAverage' || args[0].length !== 1) return 'Start with MovingAverage and the window size.';
  const size = args[0][0];
  if (!Number.isInteger(size) || size < 1 || size > 1000) return 'size is a whole number from 1 to 1000.';
  if (operations.length - 1 > 10000) return 'At most 10^4 calls to next.';
  for (let i = 1; i < operations.length; i++) {
    if (operations[i] !== 'next') return 'Only next can follow the constructor.';
    if (args[i].length !== 1) return 'next takes one value.';
    const val = args[i][0];
    if (!Number.isInteger(val) || val < -100000 || val > 100000) return 'Each value is a whole number from -10^5 to 10^5.';
  }
  return null;
}

