class MovingAverage {
  constructor(size) {
    this.size = size;
    this.window = new Array(size).fill(0);
    this.count = 0;
    this.sum = 0;
  }

  next(val) {
    const slot = this.count % this.size;
    this.sum -= this.window[slot];
    this.window[slot] = val;
    this.sum += val;
    this.count++;
    const length = Math.min(this.count, this.size);
    return this.sum / length;
  }
}

