class MovingAverage {
  constructor(size) {
    // Keep the whole stream and re-add the last few values on every call.
    this.size = size;
    this.values = [];
  }
  next(val) {
    this.values.push(val);
    const recent = this.values.slice(-this.size);
    let total = 0;
    for (const v of recent) total += v;
    return total / recent.length;
  }
}

