function generate(rand, size) {
  const pick = k => Math.floor(rand() * k);
  const large = size === 'large';
  const width = large ? (rand() < 0.2 ? 1000 : 1 + pick(400)) : 1 + pick(5);
  const span = large || rand() < 0.5 ? 100000 : 10;
  const calls = large ? 499 : 1 + pick(12);
  const operations = ['MovingAverage'];
  const args = [[width]];
  for (let i = 0; i < calls; i++) {
    operations.push('next');
    args.push([pick(2 * span + 1) - span]);
  }
  return [operations, args];
}
